using System;

namespace StdbModule;

public static partial class EnglishQuotes
{
    public static class JamesBaldwin
    {
        public static readonly Quote[] Quotes = new Quote[]
        {
            new Quote { Id = "https://en.wikiquote.org/wiki/James_Baldwin", Text = "The primary distinction of the artist is that he must actively cultivate that state which most men, necessarily, must avoid: the state of being alone.", Author = "James Baldwin" },
            new Quote { Id = "https://en.wikiquote.org/wiki/James_Baldwin", Text = "Not everything that is faced can be changed; but nothing can be changed until it is faced.", Author = "James Baldwin" },
            new Quote { Id = "https://en.wikiquote.org/wiki/James_Baldwin", Text = "Despair is a sin. I believe that. It is easy to be bleak about the human race, but there are people who have proved to me that we can be better than we are.", Author = "James Baldwin" },
            new Quote { Id = "https://en.wikiquote.org/wiki/James_Baldwin", Text = "The moment we cease to hold each other, the moment we break faith with one another, the sea engulfs us and the light goes out.", Author = "James Baldwin" },
            new Quote { Id = "https://en.wikiquote.org/wiki/James_Baldwin", Text = "Everything depends on how relentlessly one forces from experience the last drop, sweet or bitter, it can possibly give.", Author = "James Baldwin" },
            new Quote { Id = "https://en.wikiquote.org/wiki/James_Baldwin", Text = "Anyone who has ever struggled with poverty knows how extremely expensive it is to be poor.", Author = "James Baldwin" },
            new Quote { Id = "https://en.wikiquote.org/wiki/James_Baldwin", Text = "Now, it is true that the nature of society is to create, among its citizens, an illusion of safety; but it is also absolutely true that the safety is always necessarily an illusion. Artists are here to disturb the peace.", Author = "James Baldwin" },
            new Quote { Id = "https://en.wikiquote.org/wiki/James_Baldwin", Text = "All over Harlem, Negro boys and girls are growing into stunted maturity, trying desperately to find a place to stand; and the wonder is not that so many are ruined but that so many survive.", Author = "James Baldwin" },
            new Quote { Id = "https://en.wikiquote.org/wiki/James_Baldwin", Text = "I imagine one of the reasons people cling to their hates so stubbornly is because they sense, once hate is gone, they will be forced to deal with pain.", Author = "James Baldwin" },
            new Quote { Id = "https://en.wikiquote.org/wiki/James_Baldwin", Text = "Sentimentality, the ostentatious parading of excessive and spurious emotion, is the mark of dishonesty, the inability to feel; the wet eyes of the sentimentalist betray his aversion to experience, his fear of life, his arid heart; and it is always, therefore, the signal of secret and violent inhumanity, the mask of cruelty.", Author = "James Baldwin" },
            new Quote { Id = "https://en.wikiquote.org/wiki/James_Baldwin", Text = "I began plotting novels at about the time I learned to read. The story of my childhood is the usual bleak fantasy, and we can dismiss it with the restrained observation that I certainly would not consider living it again.", Author = "James Baldwin" },
            new Quote { Id = "https://en.wikiquote.org/wiki/James_Baldwin", Text = "Any writer, I suppose, feels that the world into which he was born is nothing less than a conspiracy against the cultivation of his talent.", Author = "James Baldwin" },
            new Quote { Id = "https://en.wikiquote.org/wiki/James_Baldwin", Text = "One writes out of one thing only — one's own experience. Everything depends on how relentlessly one forces from this experience the last drop, sweet or bitter, it can possibly give. This is the only real concern of the artist, to recreate out of the disorder of life that order which is art.", Author = "James Baldwin" },
            new Quote { Id = "https://en.wikiquote.org/wiki/James_Baldwin", Text = "I don't like people who like me because I'm a Negro; neither do I like people who find in the same accident grounds for contempt. I love America more than any other country in the world, and, exactly for this reason, I insist on the right to criticize her perpetually. I think all theories are suspect, that the finest principles may have to be modified, or may even be pulverized by the demands of life, and that one must find, therefore, one's own moral center and move through the world hoping that this center will guide one aright.", Author = "James Baldwin" },
            new Quote { Id = "https://en.wikiquote.org/wiki/James_Baldwin", Text = "Confronted with the impossibility of remaining faithful to one’s beliefs, and the equal impossibility of becoming free of them, one can be driven to the most inhuman excesses.", Author = "James Baldwin" },
            new Quote { Id = "https://en.wikiquote.org/wiki/James_Baldwin", Text = "People are trapped in history and history is trapped in them.", Author = "James Baldwin" },
            new Quote { Id = "https://en.wikiquote.org/wiki/James_Baldwin", Text = "The betrayal of a belief is not the same thing as ceasing to believe. If this were not so there would be no moral standards in the world at all.", Author = "James Baldwin" },
            new Quote { Id = "https://en.wikiquote.org/wiki/James_Baldwin", Text = "But people can't, unhappily, invent their mooring posts, their lovers and their friends, anymore than they can invent their parents. Life gives these and also takes them away and the great difficulty is to say Yes to life.", Author = "James Baldwin" },
            new Quote { Id = "https://en.wikiquote.org/wiki/James_Baldwin", Text = "Nothing is more unbearable, once one has it, than freedom.", Author = "James Baldwin" },
            new Quote { Id = "https://en.wikiquote.org/wiki/James_Baldwin", Text = "I shall never be able to have any more of these boyish, zestful affairs — which are, really, when one thinks about it, a kind of higher, or, anyway, more pretentious masturbation. People are too various to be treated so lightly.", Author = "James Baldwin" },
            new Quote { Id = "https://en.wikiquote.org/wiki/James_Baldwin", Text = "The big fish eat the little fish and the ocean doesn't care.", Author = "James Baldwin" },
            new Quote { Id = "https://en.wikiquote.org/wiki/James_Baldwin", Text = "And, at the risk of losing forever your so remarkably candid friendship, let me tell you something. Confusion is a luxury which only the very, very young can possibly afford, and you are not that young any more.", Author = "James Baldwin" },
            new Quote { Id = "https://en.wikiquote.org/wiki/James_Baldwin", Text = "Because there is no affection in them, and no joy. It's like putting an electric plug in a dead socket. Touch, but no contact. All touch, but no contact and no light.", Author = "James Baldwin" },
            new Quote { Id = "https://en.wikiquote.org/wiki/James_Baldwin", Text = "Love him, love him and let him love you. Do you think anything else under heaven really matters? And how long, at the best, can it last, since you are both men and still have everywhere to go? Only five minutes, I assure you, only five minutes, and most of that, helas! in the dark. And if you think of them as dirty, then they will be dirty — they will be dirty because you will be giving nothing, you will be despising your flesh and his. But you can make your time together anything but dirty, you can give each other something which will make both of you better — forever — if you will not be ashamed, if you will only not play it safe. You play it safe long enough, and you'll end up trapped in your own dirty body, forever and forever and forever — like me.", Author = "James Baldwin" },
            new Quote { Id = "https://en.wikiquote.org/wiki/James_Baldwin", Text = "Somebody,' said Jacques, 'your father or mine, should have told us that not many people have ever died of love. But multitudes have perished, and are perishing every hour — and in the oddest places! — for the lack of it.", Author = "James Baldwin" },
            new Quote { Id = "https://en.wikiquote.org/wiki/James_Baldwin", Text = "Maybe everything bad that happens to you makes you weaker, and so you can stand less and less.", Author = "James Baldwin" },
            new Quote { Id = "https://en.wikiquote.org/wiki/James_Baldwin", Text = "I felt so aimless — like a tennis ball, bouncing, bouncing — I began to wonder where I'd land.", Author = "James Baldwin" },
            new Quote { Id = "https://en.wikiquote.org/wiki/James_Baldwin", Text = "Much has been written of love turning to hatred, of the heart growing cold with the death of love. It is a remarkable process. It is far more terrible than anything I have ever read about it, more terrible than anything I will ever be able to say.", Author = "James Baldwin" },
            new Quote { Id = "https://en.wikiquote.org/wiki/James_Baldwin", Text = "Any real change implies the breakup of the world as one has always known it, the loss of all that gave one an identity, the end of safety. And at such a moment, unable to see and not daring to imagine what the future will now bring forth, one clings to what one knew, or dreamed that one possessed. Yet, it is only when a man is able, without bitterness or self-pity, to surrender a dream he has long cherished or a privilege he has long possessed that he is set free — he has set himself free — for higher dreams, for greater privileges.", Author = "James Baldwin" },
            new Quote { Id = "https://en.wikiquote.org/wiki/James_Baldwin", Text = "I have not written about being a Negro at such length because I do not expect that to be my only subject, but only because it was the gate I had to unlock before I could hope to write about anything else.", Author = "James Baldwin" },
            new Quote { Id = "https://en.wikiquote.org/wiki/James_Baldwin", Text = "All art is a kind of confession, more or less oblique. All artists, if they are to survive, are forced, at last, to tell the whole story, to vomit the anguish up.", Author = "James Baldwin" },
            new Quote { Id = "https://en.wikiquote.org/wiki/James_Baldwin", Text = "At the rate things are going here, all of Africa will be free before we can get a lousy cup of coffee.", Author = "James Baldwin" },
            new Quote { Id = "https://en.wikiquote.org/wiki/James_Baldwin", Text = "I conceive of God, in fact, as a means of liberation and not a means to control others.", Author = "James Baldwin" },
            new Quote { Id = "https://en.wikiquote.org/wiki/James_Baldwin", Text = "Love does not begin and end the way we seem to think it does. Love is a battle, love is a war; love is a growing up.", Author = "James Baldwin" },
            new Quote { Id = "https://en.wikiquote.org/wiki/James_Baldwin", Text = "The price one pays for pursuing any profession or calling is an intimate knowledge of its ugly side.", Author = "James Baldwin" },
            new Quote { Id = "https://en.wikiquote.org/wiki/James_Baldwin", Text = "Nobody is more dangerous than he who imagines himself pure in heart; for his purity, by definition, is unassailable.", Author = "James Baldwin" },
            new Quote { Id = "https://en.wikiquote.org/wiki/James_Baldwin", Text = "The roles that we construct are constructed because we feel that they will help us to survive and also, of course, because they fulfill something in our personalities; and one does not, therefore, cease playing a role simply because one has begun to understand it. All roles are dangerous. The world tends to trap you in the role you play and it is always extremely hard to maintain a watchful, mocking distance between oneself as one appears to be and oneself as one actually is.", Author = "James Baldwin" },
            new Quote { Id = "https://en.wikiquote.org/wiki/James_Baldwin", Text = "Money, it turned out, was exactly like sex. You thought of nothing else if you didn't have it and thought of other things if you did.", Author = "James Baldwin" },
            new Quote { Id = "https://en.wikiquote.org/wiki/James_Baldwin", Text = "Art has to be a kind of confession. I don't mean a true confession in the sense of that dreary magazine. The effort it seems to me, is: if you can examine and face your life, you can discover the terms with which you are connected to other lives, and they can discover them, too — the terms with which they are connected to other people.", Author = "James Baldwin" },
            new Quote { Id = "https://en.wikiquote.org/wiki/James_Baldwin", Text = "You read something which you thought only happened to you, and you discover that it happened 100 years ago to Dostoyevsky. This is a very great liberation for the suffering, struggling person, who always thinks that he is alone. This is why art is important. Art would not be important if life were not important, and life is important.", Author = "James Baldwin" },
            new Quote { Id = "https://en.wikiquote.org/wiki/James_Baldwin", Text = "Most of us, no matter what we say, are walking in the dark, whistling in the dark. Nobody knows what is going to happen to him from one moment to the next, or how one will bear it. This is irreducible. And it's true of everybody. Now, it is true that the nature of society is to create, among its citizens, an illusion of safety; but it is also absolutely true that the safety is always necessarily an illusion. Artists are here to disturb the peace.", Author = "James Baldwin" },
            new Quote { Id = "https://en.wikiquote.org/wiki/James_Baldwin", Text = "Chicagoans talk about Mississippi as though they had no South Side. White people in New York talk about Alabama as though they had no Harlem. To ignore what is happening in their own back yard is a great device on the part of the white people.", Author = "James Baldwin" },
            new Quote { Id = "https://en.wikiquote.org/wiki/James_Baldwin", Text = "If one could accept the fact that it is no longer important to be white, it would begin to cease to be important to be black. If we could accept the fact that no nation with 20 million black people in it for so long and with such a depth of involvement, that no nation under these circumstances can be called a white nation, this would be a great achievement, and it would change a great many things.", Author = "James Baldwin" },
            new Quote { Id = "https://en.wikiquote.org/wiki/James_Baldwin", Text = "One of the reasons, for example, I think that our youth is so badly educated and it is inconceivably badly educated-is because education demands a certain daring, a certain independence of mind. You have to teach some people to think; and in order to teach some people to think, you have to teach them to think about everything. There mustn't be something they can not think about. If there is one thing they can not think about, very shortly they can't think about anything.", Author = "James Baldwin" },
            new Quote { Id = "https://en.wikiquote.org/wiki/James_Baldwin", Text = "If you don't know what happened behind you, you've no idea of what is happening around you.", Author = "James Baldwin" },
            new Quote { Id = "https://en.wikiquote.org/wiki/James_Baldwin", Text = "Whatever white people do not know about Negroes reveals, precisely and inexorably, what they do not know about themselves.", Author = "James Baldwin" },
            new Quote { Id = "https://en.wikiquote.org/wiki/James_Baldwin", Text = "It will be a great day for America, incidentally, when we begin to eat bread again, instead of the blasphemous and tasteless foam rubber that we have substituted for it. And I am not being frivolous here, either. Something very sinister happens to the people of a country when they begin to distrust their own reactions as deeply as they do here, and become as joyless as they have become.", Author = "James Baldwin" },
            new Quote { Id = "https://en.wikiquote.org/wiki/James_Baldwin", Text = "If the word integration means anything, this is what it means: that we, with love, shall force our brothers to see themselves as they are, to cease fleeing from reality and begin to change it.", Author = "James Baldwin" },
            new Quote { Id = "https://en.wikiquote.org/wiki/James_Baldwin", Text = "Perhaps the whole root of our trouble, the human trouble, is that we will sacrifice all the beauty of our lives, will imprison ourselves in totems, taboos, crosses, blood sacrifices, steeples, mosques, races, armies, flags, nations, in order to deny the fact of death, which is the only fact we have.", Author = "James Baldwin" },
            new Quote { Id = "https://en.wikiquote.org/wiki/James_Baldwin", Text = "Christianity has operated with an unmitigated arrogance and cruelty — necessarily, since a religion ordinarily imposes on those who have discovered the true faith the spiritual duty of liberating the infidels.", Author = "James Baldwin" },
            new Quote { Id = "https://en.wikiquote.org/wiki/James_Baldwin", Text = "If the concept of God has any validity or any use, it can only be to make us larger, freer, and more loving. If God cannot do this, then it is time we got rid of Him.", Author = "James Baldwin" },
            new Quote { Id = "https://en.wikiquote.org/wiki/James_Baldwin", Text = "I do not know many Negroes who are eager to be 'accepted' by white people, still less to be loved by them; they, the blacks, simply don't wish to be beaten over the head by the whites every instant of our brief passage on this planet. White people will have quite enough to do in learning how to accept and love themselves and each other, and when they have achieved this — which will not be tomorrow and may very well be never — the Negro problem will no longer exist, for it will no longer be needed.", Author = "James Baldwin" },
            new Quote { Id = "https://en.wikiquote.org/wiki/James_Baldwin", Text = "I speak as an American Negro. I challenge anyone alive to tell me why any black American should go into those jungles to kill people who are not white and who have never done him any harm, in defense of a people who have made that foreign jungle, or any jungle anywhere in the world, a more desirable jungle than that in which he was born, and to which, supposing that he lives, he will inevitably return.", Author = "James Baldwin" },
            new Quote { Id = "https://en.wikiquote.org/wiki/James_Baldwin", Text = "The American war in Vietnam raises several questions. One is whether or not small nations, in this age of super-states and and live as they feel they should. For only the people of a superpowers, will be allowed to work out their own destinies country have the right, or the spiritual power, to determine that country's way of life.", Author = "James Baldwin" },
            new Quote { Id = "https://en.wikiquote.org/wiki/James_Baldwin", Text = "Another question this war raises is just how what we call the under-developed countries became under developed in the first place. Why, for example, is Africa under-populated, and why do the resources of, say, Sierra Leone belong to Europe? Why, in short, does so much of the world eat too little and so little of the world eat too much?", Author = "James Baldwin" },
            new Quote { Id = "https://en.wikiquote.org/wiki/James_Baldwin", Text = "Long, long before the Americans decided to liberate the Southeast Asians, they decided to liberate me: my ancestors carried these scars to the grave, and so will I. A racist society can't but fight a racist war-this is the bitter truth. The assumptions acted on at home are also acted on abroad, and every American Negro knows this, for he, after the American Indian, was the first \"Viet Cong\" victim. We were bombed first. How, then, can I believe a word you say, and what gives you the right to ask me to die for you?", Author = "James Baldwin" },
            new Quote { Id = "https://en.wikiquote.org/wiki/James_Baldwin", Text = "The American endeavor in Vietnam is totally indefensible and totally doomed, and I wish to go on record as having no part of it. When the black population of America has a future, so will America have a future-not till then. And when the black populations of the world have a future, so will the Western nations have a future-and not till then.", Author = "James Baldwin" },
            new Quote { Id = "https://en.wikiquote.org/wiki/James_Baldwin", Text = "I think that mankind can do better than that, and I wish to be a witness to this small and stubborn possibility.", Author = "James Baldwin" },
            new Quote { Id = "https://en.wikiquote.org/wiki/James_Baldwin", Text = "A child’s major attention has to be concentrated on how to fit into a world which, with every passing hour, reveals itself as merciless.", Author = "James Baldwin" },
            new Quote { Id = "https://en.wikiquote.org/wiki/James_Baldwin", Text = "Now, for the first time, I began to be aware of my heart, the heart itself: and with this awareness, conscious terror came. I realized that I knew nothing whatever about the way we are put together; and I realized that what I did not know might be in the process of killing me.", Author = "James Baldwin" },
            new Quote { Id = "https://en.wikiquote.org/wiki/James_Baldwin", Text = "Some moments in a life, and they needn’t be very long or seem very important, can make up for so much in that life; can redeem, justify, that pain, that bewilderment, with which one lives, and invest one with the courage not only to endure it, but to profit from it; some moments teach one the price of the human connection: if one can live with one’s own pain, then one respects the pain of others, and so, briefly, but transcendentally, we can release each other from pain.", Author = "James Baldwin" },
            new Quote { Id = "https://en.wikiquote.org/wiki/James_Baldwin", Text = "Everyone wishes to be loved, but, in the event, nearly no one can bear it. Everyone desires love but also finds it impossible to believe that he deserves it.", Author = "James Baldwin" },
            new Quote { Id = "https://en.wikiquote.org/wiki/James_Baldwin", Text = "The prison is overcrowded, the calendars full, the judges busy, the lawyers ambitious, and the cops zealous. What does it matter if someone gets trapped here for a year or two, gets ruined here, goes mad here, commits murder or suicide here? It's too bad, but that's the way the cookie crumbles sometimes. I do not claim that everyone in prison here is innocent, but I do claim that the law, as it operates, is guilty, and that the prisoners, therefore, are all unjustly imprisoned.", Author = "James Baldwin" },
            new Quote { Id = "https://en.wikiquote.org/wiki/James_Baldwin", Text = "Well, if one really wishes to know how justice is administered in a country, one does not question the policemen, the lawyers, the judges, or the protected members of the middle class. One goes to the unprotected — those, precisely, who need the law's protection most! — and listens to their testimony. Ask any Mexican, any Puerto Rican, any black man, any poor person — ask the wretched how they fare in the halls of justice, and then you will know, not whether or not the country is just, but whether or not it has any love for justice, or any concept of it. It is certain, in any case, that ignorance, allied with power, is the most ferocious enemy justice can have.", Author = "James Baldwin" },
            new Quote { Id = "https://en.wikiquote.org/wiki/James_Baldwin", Text = "People pay for what they do, and, still more, for what they have allowed themselves to become. And they pay for it very simply: by the lives they lead.", Author = "James Baldwin" },
            new Quote { Id = "https://en.wikiquote.org/wiki/James_Baldwin", Text = "People who treat other people as less than human must not be surprised when the bread they have cast on the waters comes floating back to them, poisoned.", Author = "James Baldwin" },
            new Quote { Id = "https://en.wikiquote.org/wiki/James_Baldwin", Text = "There is a reason, after all, that some people wish to colonize the moon, and others dance before it as before an ancient friend.", Author = "James Baldwin" },
            new Quote { Id = "https://en.wikiquote.org/wiki/James_Baldwin", Text = "Passion is terrifying, it can rock you, change you, bring your head under, as when a wind rises from the bottom of the sea, and you're out there in the craft of your mortality, alone.", Author = "James Baldwin" },
            new Quote { Id = "https://en.wikiquote.org/wiki/James_Baldwin", Text = "Close up, the person's imperfections matter, but from far away, you see your own.", Author = "James Baldwin" },
            new Quote { Id = "https://en.wikiquote.org/wiki/James_Baldwin", Text = "without love, pleasure withers quickly, becomes a foul taste on the palate, and pleasure’s inventions are soon exhausted. There must be a soul within the body you are holding, a soul which you are striving to meet, a soul which is striving to meet yours.", Author = "James Baldwin" },
            new Quote { Id = "https://en.wikiquote.org/wiki/James_Baldwin", Text = "This may be why we appear to learn absolutely nothing from experience, or may, in other words, account for our incoherence: memory does not require that we reconstitute the event, but that we justify it.", Author = "James Baldwin" },
            new Quote { Id = "https://en.wikiquote.org/wiki/James_Baldwin", Text = "It is not merely that the rain falls differently on each of you, for that can be a wonder and a joy: it is that what is rain for the one is not rain for the other.", Author = "James Baldwin" },
            new Quote { Id = "https://en.wikiquote.org/wiki/James_Baldwin", Text = "\"...but you were never really white in the first place. Nobody is. Nobody has, even, ever wanted to be white, unless they are afraid of being black. But being black is nothing to be afraid of. I knew that before I met you, and I have learned it again, through you. Perhaps being white is not a conceivable condition, but a terrifying fantasy, a moral choice.”", Author = "James Baldwin" },
            new Quote { Id = "https://en.wikiquote.org/wiki/James_Baldwin", Text = "Perhaps I did not succumb to ideology … because I have never seen myself as a spokesman. I am a witness. In the church in which I was raised you were supposed to bear witness to the truth. Now, later on, you wonder what in the world the truth is, but you do know what a lie is.", Author = "James Baldwin" },
            new Quote { Id = "https://en.wikiquote.org/wiki/James_Baldwin", Text = "You don't realize that you're intelligent until it gets you into trouble.", Author = "James Baldwin" },
            new Quote { Id = "https://en.wikiquote.org/wiki/James_Baldwin", Text = "The celebrity never sees himself. I have some idea what I'm doing on that stage; above all, I have some idea what sustains me on that stage. But the celebrity is not exactly Jimmy, though he comes out of Jimmy and Jimmy nourishes that, too. I can see now, with hindsight, that I would've had to become a celebrity in order to survive. A boy like me with all his handicaps, real and fancied, could not have survived in obscurity. I can say that it would have had to happen this way, though I could not see it coming.", Author = "James Baldwin" },
            new Quote { Id = "https://en.wikiquote.org/wiki/James_Baldwin", Text = "The real point is that people like me and Harry Belafonte and even Martin Luther King are not Negro leaders. We're doing our best to find out where the people are and to follow them.", Author = "James Baldwin" },
            new Quote { Id = "https://en.wikiquote.org/wiki/James_Baldwin", Text = "What white Americans think is happening in the world and what black people must deal with day by day are very different.", Author = "James Baldwin" },
            new Quote { Id = "https://en.wikiquote.org/wiki/James_Baldwin", Text = "A change, a real change is brought about when the people make a change. The poet or the revolutionary is there to articulate the necessity, but until the people themselves apprehend it, nothing can happen. When the people have taken the necessity, when the movement starts moving, then the world moves. Perhaps, it can't be done without the poet, but, it certainly can't be done without the people. The poet and the people get on generally very badly, and yet they need each other. The poet knows it sooner than the people do. The people usually know it after the poet is dead; but, that's all right. The point is to get your work done, and your work is to change the world.", Author = "James Baldwin" },
            new Quote { Id = "https://en.wikiquote.org/wiki/James_Baldwin", Text = "The role of the artist is exactly the same role, I think, as the role of the lover. If you love somebody, you honor at least two necessities at once. One of them is to recognize something very dangerous, or very difficult. Many people cannot recognize it at all, that you may also be loved; love is like a mirror. In any case, if you do love somebody, you honor the necessity endlessly, and being at the mercy of that love, you try to correct the person whom you love.", Author = "James Baldwin" },
            new Quote { Id = "https://en.wikiquote.org/wiki/James_Baldwin", Text = "The one thing it revealed to me was a profound nobility, a real nobility on the part of a whole lot of black people, old and young. There is no other word for it. It was a passionate example. It was doomed to political failure, but that doesn't make any difference. The example will never, never die. And on another level, it exposed white people. Some of them understood it and some of them didn't. Some of them really understood what it meant to have all those kids cattleprodded and hosed and beaten and murdered and chained and castrated. The moral image of a cattleprod against a woman's breast or against a man's testicles. It exposed some things for some people and on the other hand most of the people hid. They did not want to see it and don't see it until today. That's how we have Nixon in the White House and we see this hood Agnew on his way to jail. And then, once again, to keep the nigger in his place, they called it law and order. They brought into office law and order, but I call it the Fourth Reich.", Author = "James Baldwin" },
            new Quote { Id = "https://en.wikiquote.org/wiki/James_Baldwin", Text = "We are responsible to the future, and not to Chase Manhattan Bank.", Author = "James Baldwin" },
            new Quote { Id = "https://en.wikiquote.org/wiki/James_Baldwin", Text = "There're two things we have to do love each other and raise our children. We have to do that! The alternative, for me, would be suicide.", Author = "James Baldwin" },
            new Quote { Id = "https://en.wikiquote.org/wiki/James_Baldwin", Text = "I say a new language. I might say a new morality, which, in my terms, comes to the same thing. And that's on all levels the level of color, the level of identity, the level of sexual identity, what love means, especially in a consumer society, for example. Everything is in question, according to me. One has to forge a new language to deal with it.", Author = "James Baldwin" },
            new Quote { Id = "https://en.wikiquote.org/wiki/James_Baldwin", Text = "I read everything. I read my way out of the two libraries in Harlem by the time I was thirteen. One does learn a great deal about writing this way. First of all, you learn how little you know. It is true that the more one learns the less one knows. I'm still learning how to write. I don't know what technique is. All I know is that you have to make the reader see it. This I learned from Dostoyevsky, from Balzac.", Author = "James Baldwin" },
            new Quote { Id = "https://en.wikiquote.org/wiki/James_Baldwin", Text = "Perhaps the turning point in one's life is realizing that to be treated like a victim is not necessarily to become one.", Author = "James Baldwin" },
            new Quote { Id = "https://en.wikiquote.org/wiki/James_Baldwin", Text = "Yes, true, but not at all by death. I'm troubled over getting my work done and over all the things I've not learned. It's useless to be troubled by death, because then, of course, you can't live at all.", Author = "James Baldwin" },
            new Quote { Id = "https://en.wikiquote.org/wiki/James_Baldwin", Text = "Americans are terrified. For the first time they know that they are capable of genocide. History is built on genocide. But they can't face it. And it doesn't make any difference what Americans think that they think-they are terrified.", Author = "James Baldwin" },
            new Quote { Id = "https://en.wikiquote.org/wiki/James_Baldwin", Text = "Change does come, but not when or in the ways we want it to come. George Jackson, Malcolm X-now people all over the world were changed by them. Because they told the secret; now, the secret was out.", Author = "James Baldwin" },
            new Quote { Id = "https://en.wikiquote.org/wiki/James_Baldwin", Text = "I am not a black nationalist but some of my best friends are...Why aren't I a black nationalist? Because I don't believe it is enough to be black-one has to be human as well. We did not struggle for four hundred years just to become like the white man\".", Author = "James Baldwin" },
            new Quote { Id = "https://en.wikiquote.org/wiki/James_Baldwin", Text = "...the world is present, and the world is not white, and America is not the symbol of civilization. Neither is England. Neither is France. Something else is happening that will engulf them by and by. You, Quincy, will be here, but I'll be gone. It's the only hope the world has-that Western hegemony and civilization be contained.", Author = "James Baldwin" },
        };
    }
}